def wishes_for(key, base):
    if key in WISH: return WISH[key]
    return [f"{base} के पावन अवसर पर भगवान आपके घर सुख, शांति और समृद्धि दें। {base} की हार्दिक शुभकामनाएँ! 🙏",
            f"आपको और आपके पूरे परिवार को {base} की बहुत-बहुत शुभकामनाएँ। ईश्वर की कृपा सदा बनी रहे।"]

